create table public.player_presence (player_id uuid primary key references public.profiles(id) on delete cascade, state text not null default 'ONLINE' check(state in ('ONLINE','IN_MATCH','OFFLINE')), last_seen_at timestamptz not null default now());
create table public.friend_match_invites (id uuid primary key default gen_random_uuid(), sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, room_key text not null, status text not null default 'PENDING' check(status in ('PENDING','ACCEPTED','DECLINED','EXPIRED')), expires_at timestamptz not null default(now()+interval '10 minutes'), created_at timestamptz not null default now(), check(sender_id<>recipient_id));
create index friend_match_invites_recipient_idx on public.friend_match_invites(recipient_id,created_at desc);
alter table public.player_presence enable row level security; alter table public.friend_match_invites enable row level security;
create policy presence_self_write on public.player_presence for all to authenticated using(player_id=(select auth.uid())) with check(player_id=(select auth.uid()));
create policy presence_friend_read on public.player_presence for select to authenticated using(player_id=(select auth.uid()) or exists(select 1 from public.friendships f where f.status='ACCEPTED' and ((f.requester_id=(select auth.uid()) and f.addressee_id=player_id) or (f.addressee_id=(select auth.uid()) and f.requester_id=player_id))));
create policy invite_participants_read on public.friend_match_invites for select to authenticated using((select auth.uid()) in(sender_id,recipient_id));

create or replace function public.social_set_presence(p_state text) returns void language plpgsql security invoker set search_path='' as $$ begin if p_state not in ('ONLINE','IN_MATCH','OFFLINE') then raise exception 'INVALID_PRESENCE'; end if; insert into public.player_presence(player_id,state,last_seen_at) values(auth.uid(),p_state,now()) on conflict(player_id) do update set state=excluded.state,last_seen_at=now(); end $$;
create or replace function public.social_invite_friend(p_friend_id uuid,p_room_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare me uuid:=auth.uid(); invite_id uuid; begin if me is null then raise exception 'AUTHENTICATION_REQUIRED'; end if; if not exists(select 1 from public.friendships where status='ACCEPTED' and ((requester_id=me and addressee_id=p_friend_id) or(requester_id=p_friend_id and addressee_id=me))) then raise exception 'NOT_FRIENDS'; end if; insert into public.friend_match_invites(sender_id,recipient_id,room_key) values(me,p_friend_id,trim(p_room_key)) returning id into invite_id; return invite_id; end $$;
create or replace function public.social_respond_invite(p_invite_id uuid,p_accept boolean) returns text language plpgsql security definer set search_path='' as $$ declare me uuid:=auth.uid(); result text; begin update public.friend_match_invites set status=case when p_accept then 'ACCEPTED' else 'DECLINED' end where id=p_invite_id and recipient_id=me and status='PENDING' and expires_at>now() returning status into result; if result is null then raise exception 'INVITE_NOT_FOUND'; end if; return result; end $$;
create or replace function public.social_remove_friend(p_friend_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare me uuid:=auth.uid(); begin delete from public.friendships where (requester_id=me and addressee_id=p_friend_id) or(requester_id=p_friend_id and addressee_id=me); end $$;
create or replace function public.social_block_player(p_player_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare me uuid:=auth.uid(); begin if me=p_player_id then raise exception 'CANNOT_BLOCK_SELF'; end if; insert into public.user_blocks(blocker_id,blocked_id) values(me,p_player_id) on conflict do nothing; delete from public.friendships where (requester_id=me and addressee_id=p_player_id) or(requester_id=p_player_id and addressee_id=me); delete from public.friend_match_invites where (sender_id=me and recipient_id=p_player_id) or(sender_id=p_player_id and recipient_id=me); end $$;
create or replace function public.social_recent_opponents() returns table(player_id uuid,display_name text,player_code text,last_played_at timestamptz) language sql security definer set search_path='' as $$ select p.id,p.display_name,p.player_code,max(m.finished_at) from public.matches m join public.profiles p on p.id=case when m.player_one_id=auth.uid() then m.player_two_id else m.player_one_id end where auth.uid() in(m.player_one_id,m.player_two_id) and m.finished_at is not null group by p.id,p.display_name,p.player_code order by max(m.finished_at) desc limit 10 $$;
create or replace function public.social_friend_presence() returns table(player_id uuid,state text,last_seen_at timestamptz) language sql security definer set search_path='' as $$ select pp.player_id,case when pp.last_seen_at<now()-interval '90 seconds' then 'OFFLINE' else pp.state end,pp.last_seen_at from public.player_presence pp where exists(select 1 from public.friendships f where f.status='ACCEPTED' and ((f.requester_id=auth.uid() and f.addressee_id=pp.player_id)or(f.addressee_id=auth.uid() and f.requester_id=pp.player_id))) $$;
create or replace function public.social_pending_invites() returns table(invite_id uuid,sender_id uuid,sender_name text,room_key text,status text,expires_at timestamptz) language sql security definer set search_path='' as $$ select i.id,i.sender_id,p.display_name,i.room_key,i.status,i.expires_at from public.friend_match_invites i join public.profiles p on p.id=i.sender_id where i.recipient_id=auth.uid() and i.status='PENDING' and i.expires_at>now() order by i.created_at desc limit 5 $$;
create or replace function public.competition_nearby() returns table(rank bigint,display_name text,player_code text,trophies integer,tier text,is_me boolean) language sql security definer set search_path='' as $$ with ranked as(select row_number() over(order by e.trophies desc,e.wins desc) rank,p.id,p.display_name,p.player_code,e.trophies from public.league_entries e join public.profiles p on p.id=e.player_id join public.league_seasons s on s.id=e.season_id where s.active), me as(select rank from ranked where id=auth.uid()) select r.rank,r.display_name,r.player_code,r.trophies,case when r.trophies>=800 then 'ELITE' when r.trophies>=400 then 'GOLD' when r.trophies>=150 then 'SILVER' else 'BRONZE' end,r.id=auth.uid() from ranked r,me where r.rank between me.rank-3 and me.rank+3 order by r.rank $$;
alter table public.league_seasons add column if not exists cadence text not null default 'MONTHLY' check(cadence in('WEEKLY','MONTHLY')); alter table public.league_seasons add column if not exists reward_item_id text references public.cosmetic_items(id);
insert into public.cosmetic_items(id,name,kind,accent) values ('badge-bronze-season','Bronz Sezon','BADGE','#B87A4B'),('badge-silver-season','Gümüş Sezon','BADGE','#C7D2DA'),('badge-gold-season','Altın Sezon','BADGE','#F4C95D'),('badge-elite-season','Elit Sezon','BADGE','#B896FF') on conflict(id) do nothing;
create table public.season_reward_claims(season_id uuid not null references public.league_seasons(id) on delete cascade,player_id uuid not null references public.profiles(id) on delete cascade,item_id text not null references public.cosmetic_items(id),claimed_at timestamptz not null default now(),primary key(season_id,player_id)); alter table public.season_reward_claims enable row level security; create policy own_season_rewards on public.season_reward_claims for select to authenticated using(player_id=(select auth.uid()));
create or replace function public.competition_claim_season_reward(p_season_id uuid) returns text language plpgsql security definer set search_path='' as $$ declare me uuid:=auth.uid(); points integer; reward text; begin select e.trophies into points from public.league_entries e join public.league_seasons s on s.id=e.season_id where e.season_id=p_season_id and e.player_id=me and s.ends_at<=now(); if points is null then raise exception 'REWARD_UNAVAILABLE'; end if; reward:=case when points>=800 then 'badge-elite-season' when points>=400 then 'badge-gold-season' when points>=150 then 'badge-silver-season' else 'badge-bronze-season' end; insert into public.user_cosmetics(player_id,item_id) values(me,reward) on conflict do nothing; insert into public.season_reward_claims(season_id,player_id,item_id) values(p_season_id,me,reward) on conflict(season_id,player_id) do update set item_id=excluded.item_id; return reward; end $$;
revoke all on function public.social_set_presence(text),public.social_invite_friend(uuid,text),public.social_respond_invite(uuid,boolean),public.social_remove_friend(uuid),public.social_block_player(uuid),public.social_recent_opponents(),public.social_friend_presence(),public.social_pending_invites(),public.competition_nearby() from public,anon;
revoke all on function public.competition_claim_season_reward(uuid) from public,anon;
grant execute on function public.social_set_presence(text),public.social_invite_friend(uuid,text),public.social_respond_invite(uuid,boolean),public.social_remove_friend(uuid),public.social_block_player(uuid),public.social_recent_opponents(),public.social_friend_presence(),public.social_pending_invites(),public.competition_nearby() to authenticated;
grant execute on function public.competition_claim_season_reward(uuid) to authenticated;
